CREATE TABLE "sources" ("source_id" TEXT PRIMARY KEY, "title" TEXT, "url" TEXT, "publisher" TEXT, "academic_year" TEXT, "published_at" TEXT, "checked_at" TEXT, "human_verified_at" TEXT, "status" TEXT, "scope" TEXT, "notes" TEXT);
CREATE TABLE "institutions" ("institution_id" TEXT PRIMARY KEY, "name" TEXT, "acronym" TEXT, "city" TEXT, "sector" TEXT, "sector_detail" TEXT, "entity_type" TEXT, "parent_name" TEXT, "address" TEXT, "source_id" TEXT, "source_locator" TEXT, "source_year" TEXT, "status" TEXT, "city_status" TEXT, "notes" TEXT, FOREIGN KEY("source_id") REFERENCES "sources"("source_id"));
CREATE TABLE "programs" ("program_id" TEXT PRIMARY KEY, "institution_id" TEXT, "name" TEXT, "description" TEXT, "degree_type" TEXT, "duration_months" INTEGER, "duration_scope" TEXT, "entry_route" TEXT, "direct_post_bac" BOOLEAN, "annual_cost" REAL, "annual_cost_currency" TEXT, "accepted_bac_types" TEXT, "required_subjects" TEXT, "interests" TEXT, "skills" TEXT, "career_paths" TEXT, "matching_status" TEXT, "curriculum_summary" TEXT, "options" TEXT, "source_id" TEXT, "source_locator" TEXT, "academic_year" TEXT, "checked_at" TEXT, "status" TEXT, "admissions_current_verified" BOOLEAN, "application_open" TEXT, "accreditation_start" TEXT, "accreditation_end" TEXT, "accreditation_status" TEXT, "notes" TEXT, "field" TEXT, "matching_basis" TEXT, "career_paths_status" TEXT, "exploration_visible" BOOLEAN, FOREIGN KEY("institution_id") REFERENCES "institutions"("institution_id"), FOREIGN KEY("source_id") REFERENCES "sources"("source_id"));
CREATE TABLE "careers" ("career_id" TEXT PRIMARY KEY, "name" TEXT, "description" TEXT, "provenance" TEXT, "employment_guaranteed" BOOLEAN);
CREATE TABLE "accreditation_history" ("institution_name" TEXT, "acronym" TEXT, "city" TEXT, "name" TEXT, "options" TEXT, "degree_raw" TEXT, "duration_raw" TEXT, "accreditation_start" TEXT, "accreditation_end" TEXT, "bulletin_officiel" TEXT, "source_line_start" INTEGER, "source_line_end" INTEGER, "accreditation_id" TEXT PRIMARY KEY, "institution_id" TEXT, "source_id" TEXT, "source_locator" TEXT, "start_year" INTEGER, "end_year" INTEGER, "program_id" TEXT, FOREIGN KEY("institution_id") REFERENCES "institutions"("institution_id"), FOREIGN KEY("source_id") REFERENCES "sources"("source_id"), FOREIGN KEY("program_id") REFERENCES "programs"("program_id"));
CREATE TABLE "admissions" ("admission_id" TEXT PRIMARY KEY, "program_id" TEXT, "criterion_type" TEXT, "value" TEXT, "academic_year" TEXT, "source_id" TEXT, "status" TEXT, "usable_for_hard_filter" BOOLEAN, FOREIGN KEY("program_id") REFERENCES "programs"("program_id"), FOREIGN KEY("source_id") REFERENCES "sources"("source_id"));
CREATE TABLE "program_careers" ("program_id" TEXT, "career_id" TEXT, "relation" TEXT, "source_id" TEXT, FOREIGN KEY("program_id") REFERENCES "programs"("program_id"), FOREIGN KEY("career_id") REFERENCES "careers"("career_id"), FOREIGN KEY("source_id") REFERENCES "sources"("source_id"));
CREATE TABLE "program_sources" ("program_id" TEXT, "source_id" TEXT, "locator" TEXT, FOREIGN KEY("program_id") REFERENCES "programs"("program_id"), FOREIGN KEY("source_id") REFERENCES "sources"("source_id"));
CREATE TABLE "pathways" ("pathway_id" TEXT PRIMARY KEY, "title" TEXT, "steps" TEXT, "source_ids" TEXT, "status" TEXT, "notes" TEXT);
CREATE TABLE "id_crosswalk" ("previous_id" TEXT, "new_id" TEXT, "entity" TEXT, "previous_file" TEXT, "reason" TEXT);
CREATE TABLE "quality_issues" ("issue_id" TEXT PRIMARY KEY, "severity" TEXT, "detail" TEXT, "impact" TEXT);